  "sim.report.feedbackMid": "{client} कुछ छोटी शंकाओं के साथ प्रोजेक्ट स्वीकार करता है। उद्देश्यों की समीक्षा करें और अपने स्कोर को बेहतर करने के लिए दोबारा खेलने पर विचार करें।",
  "sim.report.feedbackLow": "{client} ने संशोधनों का अनुरोध किया है। प्रोजेक्ट ब्रीफ को ध्यान से पढ़ें और आवश्यक मानकों को पूरा करने के लिए फिर से प्रयास करें।",
