  "aptitude.shareTitle": "करियर एपटिट्यूड टेस्ट - VisionEx Academy",
  "aptitude.q1": "आप अपनी खाली समय में समय बिताना कैसे पसंद करेंगे?",
  "aptitude.q1.a": "किताबें या वैज्ञानिक लेख पढ़ना",
  "aptitude.q1.b": "ड्रॉइंग, डिजाइनिंग, या संगीत बजाना",
  "aptitude.q1.c": "खेलकूद या शारीरिक गतिविधियाँ करना",
  "aptitude.q1.d": "दोस्तों से बात करना और दूसरों की मदद करना",
  "aptitude.q2": "आपको सबसे ज़्यादा कौन-सा स्कूल विषय पसंद है?",
  "aptitude.q2.a": "गणित और विज्ञान",
  "aptitude.q2.b": "भाषाएँ और साहित्य",
  "aptitude.q2.c": "कला और डिज़ाइन",
  "aptitude.q2.d": "अर्थशास्त्र और व्यापार",
  "aptitude.q3": "आप काम कैसे करना पसंद करते हैं?",
  "aptitude.q3.a": "गहरे फोकस के साथ अकेले",
  "aptitude.q3.b": "टीम में, दूसरों के साथ मिलकर",
  "aptitude.q3.c": "टीम का नेतृत्व करना और निर्णय लेना",
  "aptitude.q3.d": "हाथों से किए जाने वाले व्यावहारिक काम करना",
  "aptitude.q4": "भविष्य के करियर में आपके लिए सबसे ज़्यादा क्या महत्वपूर्ण है?",
  "aptitude.q4.a": "उच्च वेतन और वित्तीय स्थिरता",
  "aptitude.q4.b": "लोगों की मदद करना और समुदाय की सेवा करना",
  "aptitude.q4.c": "रचनात्मकता और नवाचार",
  "aptitude.q4.d": "काम में आज़ादी और लचीलापन",
  "aptitude.q5": "इनमें से कौन-सा प्रोजेक्ट आपको सबसे ज़्यादा रोमांचित करता है?",
  "aptitude.q5.a": "ऐप या वेबसाइट बनाना",
  "aptitude.q5.b": "किसी प्रोडक्ट या ब्रांड को डिज़ाइन करना",
  "aptitude.q5.c": "वैज्ञानिक प्रयोग या रिसर्च करना",
  "aptitude.q5.d": "किसी इवेंट का आयोजन या प्रोजेक्ट मैनेज करना",
  "aptitude.q6": "जब आप किसी कठिन समस्या का सामना करते हैं, तो आप क्या करते हैं?",
  "aptitude.q6.a": "तर्क के साथ इसे चरण-दर-चरण विश्लेषित करें",
  "aptitude.q6.b": "रचनात्मक, पारंपरिक से हटकर समाधान ढूँढें",
  "aptitude.q6.c": "मदद माँगें और दूसरों के साथ चर्चा करें",
  "aptitude.q6.d": "सीधे व्यावहारिक समाधान आज़माएँ",
  "aptitude.q7": "आप भविष्य में खुद को कहाँ काम करते हुए देखते हैं?",
  "aptitude.q7.a": "किसी ऑफिस या टेक कंपनी में",
  "aptitude.q7.b": "किसी अस्पताल या क्लिनिक में",
  "aptitude.q7.c": "किसी क्रिएटिव स्टूडियो या वर्कशॉप में",
  "aptitude.q7.d": "बाहर खुले में या बहुत यात्रा करते हुए",
